#!/usr/bin/env bash
# Render ~/.config/colors/palette.toml into per-tool partials.
# Consumers @import the generated files; do not edit them by hand.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
PALETTE="$ROOT/palette.toml"
EWW_OUT="$HOME/.config/eww/bar/_palette.scss"
ROFI_OUT="$HOME/.config/rofi/_palette.rasi"
KITTY_OUT="$HOME/.config/kitty/_palette.conf"
NVIM_OUT="$HOME/.config/nvim/lua/_palette.lua"
GTK3_OUT="$HOME/.config/gtk-3.0/_palette.css"
GTK4_OUT="$HOME/.config/gtk-4.0/_palette.css"
HYPR_OUT="$HOME/.config/hypr/_palette.lua"
FASTFETCH_OUT="$HOME/.config/fastfetch/config.jsonc"
KDE_OUT="$ROOT/_kde.colors"
KDE_SCHEME_NAME="CallOfTheNight"

if [[ ! -f "$PALETTE" ]]; then
  echo "error: $PALETTE not found" >&2
  exit 1
fi

load_section() {
  local section=$1 prefix=$2
  yq -p toml -o json ".$section" "$PALETTE" \
    | jq -r --arg p "$prefix" '
        to_entries[] |
        $p + (.key | gsub("-"; "_") | ascii_upcase) + "=" + (.value | @sh)
      '
}

eval "$(load_section colors   C_)"
eval "$(load_section geometry G_)"

mkdir -p "$(dirname "$EWW_OUT")" "$(dirname "$ROFI_OUT")" "$(dirname "$KITTY_OUT")" "$(dirname "$NVIM_OUT")" \
  "$(dirname "$GTK3_OUT")" "$(dirname "$GTK4_OUT")" "$(dirname "$HYPR_OUT")"

cat > "$EWW_OUT" <<EOF
// Generated by ~/.config/colors/render.sh — DO NOT EDIT.
// Source: ~/.config/colors/palette.toml

\$primary-color:            $C_PRIMARY;
\$secondary-color:          $C_SECONDARY;
\$background-color:         $C_BACKGROUND;
\$view-bg-color:            $C_VIEW_BG;
\$hover-color:              $C_HOVER;
\$overlay-background-color: $C_OVERLAY_BACKGROUND;
\$overlay-hover-color:      $C_OVERLAY_HOVER;
\$border-color:             $C_BORDER;
\$accent-color:             $C_ACCENT;
\$urgent-color:             $C_URGENT;
\$fg-color:                 $C_FG;
\$fg-muted-color:           $C_FG_MUTED;
\$border-radius:            $G_RADIUS;
EOF

cat > "$ROFI_OUT" <<EOF
/* Generated by ~/.config/colors/render.sh — DO NOT EDIT.
   Source: ~/.config/colors/palette.toml */

* {
    primary:        $C_PRIMARY;
    secondary:      $C_SECONDARY;
    bg:             $C_BACKGROUND;
    view-bg:        $C_VIEW_BG;
    hover:          $C_HOVER;
    overlay-bg:     $C_OVERLAY_BACKGROUND;
    overlay-hover:  $C_OVERLAY_HOVER;
    border-col:     $C_BORDER;
    accent:         $C_ACCENT;
    urgent:         $C_URGENT;
    fg:             $C_FG;
    fg-muted:       $C_FG_MUTED;
}
EOF

cat > "$KITTY_OUT" <<EOF
# Generated by ~/.config/colors/render.sh — DO NOT EDIT.
# Source: ~/.config/colors/palette.toml
# Mirrors Dolphin's Colors:View background (KDE color scheme).

background $C_VIEW_BG
foreground $C_FG
EOF

cat > "$NVIM_OUT" <<EOF
-- Generated by ~/.config/colors/render.sh — DO NOT EDIT.
-- Source: ~/.config/colors/palette.toml
-- Consumed by lua/plugins/dracula.lua to keep nvim's bg in sync with kitty.

return {
  primary    = "$C_PRIMARY",
  secondary  = "$C_SECONDARY",
  background = "$C_BACKGROUND",
  view_bg    = "$C_VIEW_BG",
  border     = "$C_BORDER",
  accent     = "$C_ACCENT",
  urgent     = "$C_URGENT",
  fg         = "$C_FG",
  fg_muted   = "$C_FG_MUTED",
}
EOF

# GTK3. Adwaita draws with literal colors, so gtk-3.0/gtk.css restyles widgets
# from these pal_* names; the theme_* names are for apps' own custom drawing.
cat > "$GTK3_OUT" <<EOF
/* Generated by ~/.config/colors/render.sh — DO NOT EDIT.
   Source: ~/.config/colors/palette.toml */

@define-color pal_primary    $C_PRIMARY;
@define-color pal_secondary  $C_SECONDARY;
@define-color pal_bg         $C_BACKGROUND;
@define-color pal_view_bg    $C_VIEW_BG;
@define-color pal_hover      $C_HOVER;
@define-color pal_overlay_hover $C_OVERLAY_HOVER;
@define-color pal_border     $C_BORDER;
@define-color pal_accent     $C_ACCENT;
@define-color pal_urgent     $C_URGENT;
@define-color pal_fg         $C_FG;
@define-color pal_fg_muted   $C_FG_MUTED;

@define-color theme_bg_color          $C_BACKGROUND;
@define-color theme_fg_color          $C_FG;
@define-color theme_base_color        $C_VIEW_BG;
@define-color theme_text_color        $C_FG;
@define-color theme_selected_bg_color $C_SECONDARY;
@define-color theme_selected_fg_color $C_PRIMARY;
EOF

# GTK4. libadwaita resolves its whole palette through these custom properties,
# so overriding them recolors every widget; --pal-* feed gtk-4.0/gtk.css.
cat > "$GTK4_OUT" <<EOF
/* Generated by ~/.config/colors/render.sh — DO NOT EDIT.
   Source: ~/.config/colors/palette.toml */

:root {
  --pal-radius: $G_RADIUS;
  --pal-border: $C_BORDER;
  --pal-primary: $C_PRIMARY;
  --pal-secondary: $C_SECONDARY;
  --pal-hover: $C_HOVER;
  --pal-overlay-hover: $C_OVERLAY_HOVER;
  --pal-fg-muted: $C_FG_MUTED;

  --window-bg-color: $C_BACKGROUND;
  --window-fg-color: $C_FG;
  --view-bg-color: $C_VIEW_BG;
  --view-fg-color: $C_FG;
  --headerbar-bg-color: $C_SECONDARY;
  --headerbar-fg-color: $C_FG;
  --headerbar-backdrop-color: $C_SECONDARY;
  --dialog-bg-color: $C_BACKGROUND;
  --dialog-fg-color: $C_FG;
  --popover-bg-color: $C_BACKGROUND;
  --popover-fg-color: $C_FG;
  --card-bg-color: $C_SECONDARY;
  --card-fg-color: $C_FG;
  --sidebar-bg-color: $C_SECONDARY;
  --sidebar-fg-color: $C_FG;
  --accent-bg-color: $C_PRIMARY;
  --accent-fg-color: $C_SECONDARY;
  --accent-color: $C_PRIMARY;
  --destructive-bg-color: $C_URGENT;
  --destructive-color: $C_URGENT;
}
EOF

# Hyprland builds rgba(RRGGBBAA) strings, so colors go out as bare hex.
cat > "$HYPR_OUT" <<EOF
-- Generated by ~/.config/colors/render.sh — DO NOT EDIT.
-- Source: ~/.config/colors/palette.toml

return {
  border    = "${C_BORDER#\#}",
  secondary = "${C_SECONDARY#\#}",
  radius    = ${G_RADIUS%px},
}
EOF

# Fastfetch can't @import a partial like eww/rofi, and randomize_picture.sh
# rewrites config.jsonc on every run, so we sweep palette-bound SGR escapes
# in-place. Targets only `[38;2;R;G;Bm` truecolor sequences — bold/reset
# and named-color SGRs are untouched.
hex_to_sgr_rgb() {
  local hex=${1#\#}
  printf '%d;%d;%d' "0x${hex:0:2}" "0x${hex:2:2}" "0x${hex:4:2}"
}

if [[ -f "$FASTFETCH_OUT" ]]; then
  C_PRIMARY_SGR=$(hex_to_sgr_rgb "$C_PRIMARY")
  sed -i -E \
    "s/\\\\u001b\\[38;2;[0-9]+;[0-9]+;[0-9]+m/\\\\u001b[38;2;${C_PRIMARY_SGR}m/g" \
    "$FASTFETCH_OUT"
fi

# KDE color scheme. Consumed by Dolphin / Konsole / any Qt-KDE app via a
# symlink at ~/.local/share/color-schemes/${KDE_SCHEME_NAME}.colors. KDE
# wants R,G,B triples (no hex, no alpha) so rgba palette entries are dropped.
hex_to_csv_rgb() {
  local hex=${1#\#}
  printf '%d,%d,%d' "0x${hex:0:2}" "0x${hex:2:2}" "0x${hex:4:2}"
}

K_PRIMARY=$(hex_to_csv_rgb    "$C_PRIMARY")
K_SECONDARY=$(hex_to_csv_rgb  "$C_SECONDARY")
K_BACKGROUND=$(hex_to_csv_rgb "$C_BACKGROUND")
K_VIEW_BG=$(hex_to_csv_rgb    "$C_VIEW_BG")
K_ACCENT=$(hex_to_csv_rgb     "$C_ACCENT")
K_URGENT=$(hex_to_csv_rgb     "$C_URGENT")
K_FG=$(hex_to_csv_rgb         "$C_FG")
K_FG_MUTED=$(hex_to_csv_rgb   "$C_FG_MUTED")

emit_color_group() {
  local section=$1 bg=$2 alt=$3
  cat <<EOF

[$section]
BackgroundNormal=$bg
BackgroundAlternate=$alt
ForegroundNormal=$K_FG
ForegroundInactive=$K_FG_MUTED
ForegroundActive=$K_ACCENT
ForegroundLink=$K_ACCENT
ForegroundVisited=$K_PRIMARY
ForegroundNegative=$K_URGENT
ForegroundNeutral=$K_PRIMARY
ForegroundPositive=$K_ACCENT
DecorationFocus=$K_ACCENT
DecorationHover=$K_PRIMARY
EOF
}

{
  cat <<EOF
# Generated by ~/.config/colors/render.sh — DO NOT EDIT.
# Source: ~/.config/colors/palette.toml

[General]
ColorScheme=$KDE_SCHEME_NAME
Name=$KDE_SCHEME_NAME
shadeSortColumn=true
EOF
  emit_color_group "Colors:View"          "$K_VIEW_BG"    "$K_VIEW_BG"
  emit_color_group "Colors:Window"        "$K_BACKGROUND" "$K_SECONDARY"
  emit_color_group "Colors:Button"        "$K_BACKGROUND" "$K_SECONDARY"
  emit_color_group "Colors:Tooltip"       "$K_SECONDARY"  "$K_BACKGROUND"
  emit_color_group "Colors:Complementary" "$K_SECONDARY"  "$K_BACKGROUND"
  emit_color_group "Colors:Header"        "$K_SECONDARY"  "$K_BACKGROUND"
  # Same colors again under the [Inactive] variant of the group, which KDE
  # reads for the header of an unfocused window. Breeze ships one that falls
  # back to the window background; without any variant at all the header of
  # a background window drops off the palette. The section name carries the
  # closing bracket so emit_color_group renders '[Colors:Header][Inactive]'.
  emit_color_group "Colors:Header][Inactive" "$K_SECONDARY" "$K_BACKGROUND"
  cat <<EOF

[Colors:Selection]
BackgroundNormal=$K_PRIMARY
BackgroundAlternate=$K_PRIMARY
ForegroundNormal=$K_SECONDARY
ForegroundInactive=$K_SECONDARY
ForegroundActive=$K_SECONDARY
ForegroundLink=$K_ACCENT
ForegroundVisited=$K_BACKGROUND
ForegroundNegative=$K_URGENT
ForegroundNeutral=$K_SECONDARY
ForegroundPositive=$K_SECONDARY
DecorationFocus=$K_ACCENT
DecorationHover=$K_PRIMARY

[WM]
activeBackground=$K_BACKGROUND
activeForeground=$K_FG
inactiveBackground=$K_SECONDARY
inactiveForeground=$K_FG_MUTED

# Breeze ships this disabled; state it rather than inherit a default, so an
# unfocused window is never desaturated away from the palette.
[ColorEffects:Inactive]
Enable=false
ChangeSelectionColor=false
ColorEffect=0
ContrastEffect=0
IntensityEffect=0
EOF
} > "$KDE_OUT"

# LibreOffice. UI chrome is themed via the kf6 VCL plugin (SAL_USE_VCLPLUGIN
# in hyprland.conf) which picks up the KDE scheme above. This block only
# touches the document-area Application Colors (cell/canvas bg, Calc grid,
# font, links) and the icon symbol style. The xcu is rewritten by LibreOffice
# on exit, so close it before re-running this script.
LO_XCU="$HOME/.config/libreoffice/4/user/registrymodifications.xcu"
LO_SCHEME="COLOR_SCHEME_LIBREOFFICE_AUTOMATIC"
LO_ICON="breeze_dark"

hex_to_lo_int() {
  local hex=${1#\#}
  printf '%d' "$(( 0x${hex:0:2} * 65536 + 0x${hex:2:2} * 256 + 0x${hex:4:2} ))"
}

if [[ -f "$LO_XCU" ]]; then
  if pgrep -x soffice.bin >/dev/null 2>&1; then
    echo "warn: LibreOffice is running — close it before re-running, or these xcu edits will be clobbered on exit." >&2
  fi

  LO_DOC=$(hex_to_lo_int   "$C_VIEW_BG")
  LO_FONT=$(hex_to_lo_int  "$C_FG")
  LO_GRID=$(hex_to_lo_int  "$C_FG_MUTED")
  LO_LINK=$(hex_to_lo_int  "$C_ACCENT")
  LO_VLINK=$(hex_to_lo_int "$C_PRIMARY")

  LO_CS="/org.openoffice.Office.UI/ColorScheme/ColorSchemes/org.openoffice.Office.UI:ColorScheme['${LO_SCHEME}']"

  LO_ITEMS=(
    "/org.openoffice.Office.Common/Misc|SymbolStyle|$LO_ICON"
    "${LO_CS}/DocColor|Color|$LO_DOC"
    "${LO_CS}/FontColor|Color|$LO_FONT"
    "${LO_CS}/CalcGrid|Color|$LO_GRID"
    "${LO_CS}/Links|Color|$LO_LINK"
    "${LO_CS}/LinksVisited|Color|$LO_VLINK"
  )

  LO_TARGETS=$(printf '%s\n' "${LO_ITEMS[@]}" | awk -F'|' '{print $1"|"$2}')
  LO_INJECT=$(printf '%s\n' "${LO_ITEMS[@]}" | awk -F'|' '{
    printf "<item oor:path=\"%s\"><prop oor:name=\"%s\" oor:op=\"fuse\"><value>%s</value></prop></item>\n", $1, $2, $3
  }')

  LO_TMP=$(mktemp)
  awk -v targets="$LO_TARGETS" -v inject="$LO_INJECT" '
    BEGIN {
      n = split(targets, lines, "\n")
      for (i=1; i<=n; i++) if (lines[i] != "") keys[lines[i]] = 1
    }
    {
      p = ""; nm = ""
      if (match($0, /oor:path="[^"]*"/))  p  = substr($0, RSTART+10, RLENGTH-11)
      if (match($0, /oor:name="[^"]*"/))  nm = substr($0, RSTART+10, RLENGTH-11)
      if (p != "" && nm != "" && ((p "|" nm) in keys)) next
      if ($0 ~ /<\/oor:items>/) { print inject; print; next }
      print
    }
  ' "$LO_XCU" > "$LO_TMP"
  mv "$LO_TMP" "$LO_XCU"
fi


# Obsidian. AnuPpuccin resolves every color through
# var(--ctp-custom-X, var(--ctp-ext-X, <catppuccin default>)) and never
# declares the --ctp-custom tier itself, so that tier is the theme's own
# override hook: define it and the whole theme re-colors, with no need to
# chase individual component variables. Emitted as a CSS snippet rather than
# a Style Manager preset so the vault stays a consumer of palette.toml.
# Plain body.theme-dark specificity: the plugin's <style> loads after
# snippets, so anything explicitly set in Style Manager's UI still wins.
OBS_VAULT="$HOME/Mahisoft Vault"
OBS_OUT="$OBS_VAULT/.obsidian/snippets/palette.css"
OBS_SNIPPET_NAME="palette"

# AnuPpuccin consumes these as rgb(var(--ctp-x)), so they are bare R, G, B
# triples rather than hex.
hex_to_triple() {
  local hex=${1#\#}
  printf '%d, %d, %d' "0x${hex:0:2}" "0x${hex:2:2}" "0x${hex:4:2}"
}

# Linear mix of two palette hexes, emitted as a triple. Used to fill the
# border and muted-text ramp, which palette.toml has no exact colors for.
# Third argument is the weight of the second color as a whole percent.
blend_to_triple() {
  local a=${1#\#} b=${2#\#} w=$3
  local ar=$((16#${a:0:2})) ag=$((16#${a:2:2})) ab=$((16#${a:4:2}))
  local br=$((16#${b:0:2})) bg=$((16#${b:2:2})) bb=$((16#${b:4:2}))
  printf '%d, %d, %d' \
    $(( (ar * (100 - w) + br * w + 50) / 100 )) \
    $(( (ag * (100 - w) + bg * w + 50) / 100 )) \
    $(( (ab * (100 - w) + bb * w + 50) / 100 ))
}

if [[ -d "$OBS_VAULT/.obsidian" ]]; then
  mkdir -p "$(dirname "$OBS_OUT")"

  O_BASE=$(hex_to_triple   "$C_VIEW_BG")
  O_MANTLE=$(hex_to_triple "$C_BACKGROUND")
  O_CRUST=$(hex_to_triple  "$C_SECONDARY")

  # Ramp from the sidebar surface up to the muted foreground, then on to the
  # full foreground. Keeps Catppuccin's own ordering (surface < overlay <
  # subtext < text) so nothing that reads the ramp inverts, and lands the two
  # colors palette.toml does define on the vars Obsidian uses for muted and
  # normal text.
  O_SURFACE0=$(blend_to_triple "$C_SECONDARY" "$C_FG_MUTED" 15)
  O_SURFACE1=$(blend_to_triple "$C_SECONDARY" "$C_FG_MUTED" 28)
  O_SURFACE2=$(blend_to_triple "$C_SECONDARY" "$C_FG_MUTED" 42)
  O_OVERLAY0=$(blend_to_triple "$C_SECONDARY" "$C_FG_MUTED" 60)
  O_OVERLAY1=$(blend_to_triple "$C_SECONDARY" "$C_FG_MUTED" 80)
  O_OVERLAY2=$(hex_to_triple   "$C_FG_MUTED")
  O_SUBTEXT0=$(blend_to_triple "$C_FG_MUTED" "$C_FG" 35)
  O_SUBTEXT1=$(blend_to_triple "$C_FG_MUTED" "$C_FG" 65)
  O_TEXT=$(hex_to_triple       "$C_FG")

  O_PRIMARY=$(hex_to_triple "$C_PRIMARY")
  O_ACCENT=$(hex_to_triple  "$C_ACCENT")
  O_URGENT=$(hex_to_triple  "$C_URGENT")

  cat > "$OBS_OUT" <<EOF
/* Generated by ~/.config/colors/render.sh — DO NOT EDIT.
   Source: ~/.config/colors/palette.toml
   Theme:  AnuPpuccin (Anubis). Enable under Appearance → CSS snippets. */

body.theme-dark {
	/* -- SURFACES
	      base   = note canvas
	      mantle = sidebars, settings nav, inactive tabs; matches Dolphin's
	               Places panel, which takes KDE's Colors:Window
	      crust  = ribbon, cards, form fields, blockquotes; the recessed
	               step below mantle, mirroring KDE's Colors:Header */
	--ctp-custom-base: $O_BASE;
	--ctp-custom-mantle: $O_MANTLE;
	--ctp-custom-crust: $O_CRUST;

	/* -- FRAME
	      Obsidian defaults --titlebar-background to --background-secondary
	      and swaps in --titlebar-background-focused only while the window
	      holds focus, so the top bar changes surface when it loses focus.
	      Pin both to the focused one to hold a single color. */
	--titlebar-background: var(--background-secondary-alt);
	--titlebar-background-focused: var(--background-secondary-alt);

	/* -- MODALS
	      Obsidian chains --modal-sidebar-background to --modal-background
	      and on to --background-primary, so the settings sidebar lands on
	      the editor canvas rather than the sidebar surface. Send it to the
	      surface the workspace sidebars already use. */
	--modal-sidebar-background: var(--background-secondary);

	/* -- BORDER AND MUTED RAMP (overlay2 is --text-muted) */
	--ctp-custom-surface0: $O_SURFACE0;
	--ctp-custom-surface1: $O_SURFACE1;
	--ctp-custom-surface2: $O_SURFACE2;
	--ctp-custom-overlay0: $O_OVERLAY0;
	--ctp-custom-overlay1: $O_OVERLAY1;
	--ctp-custom-overlay2: $O_OVERLAY2;

	/* -- TEXT (text is --text-normal, subtext0 is --text-faint) */
	--ctp-custom-text: $O_TEXT;
	--ctp-custom-subtext1: $O_SUBTEXT1;
	--ctp-custom-subtext0: $O_SUBTEXT0;

	/* -- ACCENTS */
	--ctp-custom-mauve: $O_PRIMARY;
	--ctp-custom-sky: $O_ACCENT;
	--ctp-custom-red: $O_URGENT;

	/* AnuPpuccin declares --ctp-accent only inside its accent-toggle
	   classes, so with no toggle picked it resolves to nothing at all.
	   Point it at the palette primary; a toggle chosen in Style Manager
	   outranks this and still wins. */
	--ctp-accent: var(--ctp-mauve);
}
EOF

  # Register the snippet in appearance.json. Obsidian rewrites this file on
  # exit, so it must be closed when this runs.
  OBS_APPEARANCE="$OBS_VAULT/.obsidian/appearance.json"
  if [[ -f "$OBS_APPEARANCE" ]]; then
    if pgrep -x obsidian >/dev/null 2>&1; then
      echo "warn: Obsidian is running — close it before re-running, or the appearance.json edit will be clobbered on exit." >&2
    fi
    OBS_TMP=$(mktemp)
    jq --arg s "$OBS_SNIPPET_NAME" --arg a "$C_PRIMARY" '
      .enabledCssSnippets = ((.enabledCssSnippets // []) + [$s] | unique)
      | .accentColor = $a
      | .theme = "obsidian"
    ' "$OBS_APPEARANCE" > "$OBS_TMP"
    mv "$OBS_TMP" "$OBS_APPEARANCE"
  fi
fi

echo "Rendered:"
echo "  $EWW_OUT"
echo "  $ROFI_OUT"
echo "  $KITTY_OUT"
echo "  $NVIM_OUT"
echo "  $GTK3_OUT"
echo "  $GTK4_OUT"
echo "  $HYPR_OUT"
echo "  $KDE_OUT"
[[ -f "$FASTFETCH_OUT" ]] && echo "  $FASTFETCH_OUT (in-place SGR sweep)"
[[ -f "$LO_XCU"        ]] && echo "  $LO_XCU (in-place xcu patch)"
if [[ -f "$OBS_OUT" ]]; then echo "  $OBS_OUT"; fi
